 const pattern=panel.querySelector('[data-action="pattern"]');if(pattern){const field=pattern.closest('.field');field.querySelector(':scope>span').textContent='تأثير الخلفية';field.querySelector('[data-value="dots"]').textContent='توهج';appearance.append(field);field.insertAdjacentHTML('beforeend','<small>سادة: صورتك الأصلية دون طبقات أو لمعة. توهج: تأثير ضوئي اختياري فوق الخلفية.</small>');}
 const shine=panel.querySelector('[data-studio="glassShine"]');if(shine)shine.closest('label').remove();
 const elements=group('عناصر الولاء والرصيد','شكل العنصر قبل الزيارة وبعدها، وطريقة عرض العداد.');

 const iconOptions=panel.querySelector('.icon-options');if(iconOptions)elements.append(iconOptions.closest('.field'));
 move('#stamp-empty-file',elements);move('#stamp-file',elements);
 const before=elements.querySelector('#stamp-empty-file')?.closest('.field')?.querySelector(':scope>span');if(before)before.textContent='صورة العنصر قبل الزيارة · اختياري';
 const after=elements.querySelector('#stamp-file')?.closest('.field')?.querySelector(':scope>span');if(after)after.textContent='صورة العنصر بعد الزيارة · اختياري';
 elements.insertAdjacentHTML('beforeend',cardToggle('stampEmphasis','تمييز العناصر المكتملة',draft.stampEmphasis!==false)+cardToggle('elementsGlow','إضاءة جميع العناصر',draft.elementsGlow===true)+cardToggle('completedGlow','إضاءة العناصر المكتملة',draft.completedGlow===true));
 elements.insertAdjacentHTML('beforeend','<p class="line-meta">عند إيقاف التمييز، تظهر جميع العناصر بوضوحها الطبيعي وتتغير الصورة فقط.</p>');
 elements.insertAdjacentHTML('beforeend','<p class="line-meta">تتبدل الصورتان تلقائيًا حسب رصيد العميل. عند عدم رفع صور، نستخدم الأيقونة التي اخترتها.</p>');
 const balance=controls.querySelector('[data-enhance="balanceStyle"]')?.closest('details');if(balance){balance.querySelector('summary').textContent='مظهر عداد الزيارات والنقاط';elements.append(balance);}
 const positioning=advanced(elements,'ترتيب العناصر وأماكنها · اختياري');positioning.insertAdjacentHTML('beforeend',offsetControl('backgroundDim','تعتيم الخلفية وإبراز العناصر',draft.backgroundDim??0,0,85)+'<p class="line-meta">اسحب لزيادة التعتيم؛ تتأثر الخلفية فقط، وتبقى العناصر والشعار والرمز واضحة. تكبير العناصر متاح حتى ١٦٠ بكسل.</p>');
 const itemSelect=panel.querySelector('#studio-item-select');if(itemSelect)positioning.append(itemSelect.closest('.field'));
 for(const el of Array.from(panel.querySelectorAll('[data-item-control]')))positioning.append(el.closest('.field'));
 const resetItems=panel.querySelector('[data-action="studio-reset-items"]');if(resetItems)positioning.append(resetItems);
 for(const key of ['stampX','stampY','stampSize'])move(`[data-studio="${key}"]`,positioning);
 positioning.insertAdjacentHTML('afterbegin','<p class="line-meta">اسحب العنصر في المعاينة، أو اختره وعدّل موقعه من هنا.</p>');
 const reward=group('المكافأة','اسم المكافأة وصورتها، في مكان واحد.');
 move('[data-card="reward"]',reward);move('[data-enhance="rewardEnglish"]',reward);
 const rewardPanel=controls.querySelector('#reward-image-file')?.closest('details');if(rewardPanel){for(const el of Array.from(rewardPanel.children))if(el.tagName!=='SUMMARY')reward.append(el);}
 const rewardPosition=advanced(reward,'حجم صورة المكافأة ومكانها');for(const key of ['rewardImageSize','rewardX','rewardY'])move(`[data-enhance="${key}"]`,rewardPosition);
 if(!reward.querySelector('[data-card="reward"]'))reward.insertAdjacentHTML('afterbegin','<p class="line-meta">قيمة الخصم ونوعه محددان في قسم برنامج الولاء.</p>');
 const final=group('الرمز والشروط','اختر الباركود واكتب شروط برنامجك.');
 for(const el of Array.from(old[2].children))if(!el.classList.contains('section-title'))final.append(el);
 const textPosition=advanced(textExtra,'مكان العبارة');for(const key of ['headlineX','headlineY'])move(`[data-enhance="${key}"]`,textPosition);
 const reset=panel.querySelector('[data-action="reset-card-arrangement"]');
 panel.replaceChildren(...groups);panel.classList.add('organized-editor');
 if(reset){const footer=document.createElement('div');footer.className='editor-reset';footer.append(reset);footer.insertAdjacentHTML('beforeend','<p class="line-meta">يعيد أماكن العناصر فقط، ويحافظ على الصور والنصوص وإعدادات الولاء.</p>');panel.append(footer);}
